        case PREPARED:
        case STARTED:
        case PAUSED:
        case STOPPED:
        case PLAYBACK_COMPLETED:
        case ERROR:
            mMp.reset();
            mpSetState(MPState.IDLE);
            return;

        default:
            ; // ignored
        }
        if (DBG) P.v("MP [" + mpGetState().name() + "] : reset ignored : ");
    }

