	public static void showAlertHtml(String title, String message,
			Handler handler) {
		Message msg1 = handler.obtainMessage();
		Bundle b = new Bundle();
		b.putInt("message_type", Const.UIUTILS_SHOWALERT_HTML);
		b.putString("title", title);
