    private void
    onMpStateChanged(MPState from, MPState to) {
        if (from == to)
            return;

        Iterator<PlayerStateListener> iter = mPStateLsnrl.iterator();
        while (iter.hasNext())
            iter.next().onStateChanged(from, to);

        switch (to) {
        case PAUSED:
        case INVALID:
            releaseLocks();
            break;

        case STARTED:
            acquireLocks();
            break;

        case STOPPED:
            if (null != mLoader)
                mLoader.close();
            break;
        }
    }

