        // Android MediaPlayer seek to previous position automatically.
        // And volume is preserved.
        // Below two line is useless.
        mpSeekTo(mStoredPState.pos);
        mpSetVolume(mStoredPState.vol);

        clearStoredPlayerState();
    }

