    public void
    addVideosStateListener(Object key, VideosStateListener listener) {
        eAssert(null != listener);
        mVStateLsnrl.remove(key);
        mVStateLsnrl.add(key, listener);
    }

    public void
    removeVideosStateListener(Object key) {
        mVStateLsnrl.remove(key);
    }

