    // Runtime Status
    // ------------------------------------------------------------------------
    private int                     mErrRetry = PLAYER_ERR_RETRY;
    private YTPState                mYtpS   = YTPState.IDLE;
    private int                     mLastBuffering  = -1;
    private PlayerState             mStoredPState = null;

