        case PREPARED:
        case STARTED:
        case PAUSED:
        case STOPPED:
        case PLAYBACK_COMPLETED:
        case ERROR:
            mMp.reset();
            mpSetState(MPState.IDLE);
            return;
        }
        logI("MP [" + mpGetState().name() + "] : reset ignored : ");
    }

