            lcListener = listener;
        }

        void
        clearOnListChangedListener() {
            eAssert(Utils.isUiThread());
            lcListener = null;
        }

        void
        notifyToListChangedListener() {
            if (null != lcListener)
                lcListener.onChanged(this);
        }

        boolean
        hasActiveVideo() {
            eAssert(Utils.isUiThread());
            return null != getActiveVideo();
        }

        boolean
        hasNextVideo() {
            eAssert(Utils.isUiThread());
            return hasActiveVideo()
                   && vi < (vs.length - 1);
        }

        boolean
        hasPrevVideo() {
            eAssert(Utils.isUiThread());
            return hasActiveVideo() && 0 < vi;
        }

        void
        reset() {
            eAssert(Utils.isUiThread());
            vs = null;
            vi = -1;
            notifyToListChangedListener();
        }

        void
        setVideoList(Video[] aVs) {
            eAssert(Utils.isUiThread());
            vs = aVs;
            if (null == vs || 0 >= vs.length)
                reset();
            else if(vs.length > 0)
                vi = 0;
            notifyToListChangedListener();
        }

        Video[]
        getVideoList() {
            eAssert(Utils.isUiThread());
            return vs;
        }

        void
        appendVideo(Video vids[]) {
            eAssert(Utils.isUiThread());
            Video[] newvs = new Video[vs.length + vids.length];
            System.arraycopy(vs, 0, newvs, 0, vs.length);
            System.arraycopy(vids, 0, newvs, vs.length, vids.length);
            // assigning reference is atomic operation in JAVA!
            vs = newvs;
            notifyToListChangedListener();
        }

        int
        getActiveVideoIndex() {
            return vi;
        }

        Video
        getActiveVideo() {
            eAssert(Utils.isUiThread());
            if (null != vs && 0 <= vi && vi < vs.length)
                return vs[vi];
            return null;
        }

        Video
        getNextVideo() {
            eAssert(Utils.isUiThread());
            if (!hasNextVideo())
                return null;
            return vs[vi + 1];
        }

        boolean
        moveTo(int index) {
            eAssert(Utils.isUiThread());
            if (index < 0 || index >= vs.length)
                return false;
            vi = index;
            return true;
        }

        boolean
        moveToFist() {
            eAssert(Utils.isUiThread());
            return moveTo(0);
