    //
    // Public interface
    //
    // ========================================================================
    private YTJSPlayer() {
    }

    public static YTJSPlayer
    get() {
        if (null == sInstance)
            sInstance = new YTJSPlayer();
        return sInstance;
    }

    @Override
    protected void
    finalize() {
    }

