+	static long lasthalt,lastpwl;
+	
+	/** When a UA failed on (un)registering. */
+	public void onUaRegistrationFailure(RegisterAgent reg_ra, NameAddress target,
+			NameAddress contact, String result) {
+		boolean retry = false;
+    	int i = 0;
