+    	}
+    	if (retry) {
+    		retry = false;
+    		if (SystemClock.uptimeMillis() > lastpwl + 45000) {
+				if (pwl[i] != null && !pwl[i].isHeld()) {
+					if ((!Receiver.on_wlan && Build.MODEL.contains("HTC One")) || (Receiver.on_wlan && wwl[i] == null)) {
