+		if (retry) {
+			lastpwl = SystemClock.uptimeMillis();
+			if (wl[i].isHeld()) {
+				wl[i].release();
+			}
+			register();
+			if (!wl[i].isHeld() && pwl[i] != null && pwl[i].isHeld()) pwl[i].release();
+			if (!wl[i].isHeld() && wwl[i] != null && wwl[i].isHeld()) wwl[i].release();
+		} else if (wl[i].isHeld()) {
