    private void
    mpSetStateFlag(int newStateFlag) {
        if (DBG) P.v("StateFlag : " + mMpSFlag + " => " + newStateFlag);
        int old = mMpSFlag;
        mMpSFlag = newStateFlag;
        onMpStateChanged(mMpS, old, mMpS, mMpSFlag);
    }

