+    private class VibratorThread extends Thread {
+        public void run() {
+            while (mContinueVibrating) {
+                vibrator.vibrate(VIBRATE_LENGTH);
+                SystemClock.sleep(VIBRATE_LENGTH + PAUSE_LENGTH);
+            }
+        }
+    }
