        case PREPARED:
        case STARTED:
        case PAUSED:
        case STOPPED:
        case PLAYBACK_COMPLETED:
            float volf = vol/100.0f;
            mMpVol = vol;
            mMp.setVolume(volf, volf);
            return;
        }

        logI("MP [" + mpGetState().name() + "] : setVolume ignored : ");
    }

    private int
    mpGetVolume() {
