        if (ytpIsSuspended())
            return;

        switch (mpGetState()) {
        case PREPARED:
        case STARTED:
        case PAUSED:
        case PLAYBACK_COMPLETED:
            mMp.start();
            mpSetState(MPState.STARTED);
            return;
        }
        logI("MP [" + mpGetState().name() + "] : start ignored : ");
    }

    private void
    mpStop() {
