        acquireLocks();
        clearStoredPlayerState();
        // removes auto stop that is set before.
        disableAutostop();
        mVlm.setVideoList(vs);

        if (mVlm.moveToFist()) {
            startVideo(mVlm.getActiveVideo(), false);
            Iterator<VideosStateListener> iter = mVStateLsnrl.iterator();
            while (iter.hasNext())
                iter.next().onStarted();
        }
    }

