    private void
    mpSetVolume(int vol) {
        if (null == mMp)
            return;

        switch (mpGetState()) {
        case IDLE:
        case INITIALIZED:
        case PREPARED_AUDIO:
        case PREPARED:
        case STARTED:
        case PAUSED:
        case STOPPED:
        case PLAYBACK_COMPLETED:
            float volf = vol/100.0f;
            mMpVol = vol;
            mMp.setVolume(volf, volf);
            return;
        }

        logI("MP [" + mpGetState().name() + "] : setVolume ignored : ");
    }

