    playerStart() {
        mpStart();
    }

    void
    playerPause() {
        mpPause();
    }

    void
    playerStop() {
        mpStop();
    }

    /**
     *
     * @param pos
     *   milliseconds.
     */
    void
    playerSeekTo(int pos) {
        mpSeekTo(pos);
    }


