     * Sends an XmppMsg to the specified JID or to the default notification
     * address
     * 
     * @param msg
     * @param to
     *            - the receiving jid. if null the default notification address
     *            is used
     */
    public void send(XmppMsg msg, String to) {
        if (sXmppMgr != null) {
            sXmppMgr.send(msg, to);
        } 
    }

