    private void
    callJsFunction(String func, String... args) {
        if (null == mWv)
            return;

        StringBuilder bldr = new StringBuilder("javascript:")
                .append(func)
                .append("(");
        int i = 0;
        for (i = 0; i < args.length - 1; i++)
            bldr.append("\"")
                .append(args[i])
                .append("\", ");

        if (args.length > 0)
            bldr.append("\"")
                .append(args[i])
                .append("\"");

        bldr.append(")");
        mWv.loadUrl(bldr.toString());
    }

