    getActiveVideoIndex() {
        return mVlm.getActiveVideoIndex();
    }

    MPState
    playerGetState() {
        return mpGetState();
    }

    void
    playerStart() {
        mpStart();
    }

    void
    playerPause() {
        mpPause();
    }

