	    for(int i = 0; i < imageWidth; i+=2){
	        int nPos = wh;
	        for(int j = 0; j < uvHeight; j++) {
	        	yuv[k] = data[nPos + i];
	        	yuv[k + 1] = data[nPos + i + 1];
	            k += 2;
	            nPos += imageWidth;
