                        @Override
                        public void onFailure(String failure) {
                            stopLoading();
                            Toast.makeText(NoodlesMaster.this, failure, Toast.LENGTH_LONG).show();

                            EasyTracker.getInstance(NoodlesMaster.this).send(MapBuilder
