+    onMpStateChanged(MPState from, MPState to) {
+        if (from == to)
+            return;
+
+        pvConfigureAll(mPlayerv, from, to);
+        switch (to) {
+        case PAUSED:
+            releaseLocks();
+            break;
+
+        case STARTED:
+            acquireLocks();
+            break;
+        }
+    }
+
+    private void
+    startVideo(final String videoId, int volume) {
+        eAssert(0 <= volume && volume <= 100);
+        new Thread(new Runnable() {
+            @Override
