+
+        mVideoi++;
+        if (mVideoi >= mVideos.length) {
+            mVideoi = mVideos.length;
+            playDone();
+        } else
+            startVideo(mVideos[mVideoi].videoId, mVideos[mVideoi].volume);
+    }
+
+    private void
+    startPrev() {
+        if (null == mVideos)
+            return; // do nothing
+
+        mVideoi--;
