+
+    public void
+    startVideos(final Video[] vs) {
+        eAssert(Utils.isUiThread());
+        eAssert(null != mPlayerv);
+
+        if (vs.length <= 0)
+            return;
+
+        // Stop if player is already running.
+        mpStop();
+        mpRelease();
+        mpNewInstance();
+        mpReset();
+
+        acquireLocks();
