    private void
    onMpStateChanged(MPState from, MPState to) {
        if (from == to)
            return;

        if (null != mPStateLsnr)
            mPStateLsnr.onStateChanged(from, to);

        switch (to) {
        case PAUSED:
        case INVALID:
            releaseLocks();
            break;

        case STARTED:
            acquireLocks();
            break;

        case STOPPED:
            if (null != mLoader)
                mLoader.close();
            break;
        }
    }

    private int
    getVideoQualityScore() {
        switch (Utils.getPrefQuality()) {
        case LOW:
            return YTHacker.getQScorePreferLow(YTHacker.YTQUALITY_SCORE_LOWEST);

