    setAutoStop(long millis) {
        mAutoStop.set(millis);
    }

    public void
    unsetAutoStop() {
        mAutoStop.unset();
    }

    public void
    stopVideos() {
        if (mVlm.hasActiveVideo())
            stopPlay(StopState.FORCE_STOPPED);
    }

    public String
    getActiveVideoYtId() {
        if (isVideoPlaying())
            return mVlm.getActiveVideo().ytvid;
        return null;
    }

