// Player State Diagram
// * [Playing] :  ajsStop()
//      [Playing] -> [Unstarted] -> [Video Cued]
//
// * [Unstarted] : PlayVideo()
//      [Unstarted] -> [Video Cued] -> [Buffering] -> [Playing]
//
// See Youtube player Javascript API document
public class YTJSPlayer {
