+    private final String timeToString(long time) {
+        int secs = (int)Math.floor((time + 999) / 1000.0);
+        boolean neg = false;
+        if (secs < 0) {
+            neg = true;
+            secs = -secs;
+        }
+        int mins = secs / 60;
+        secs -= mins * 60;
+        StringBuilder ret = new StringBuilder();
+        if (neg) ret.append('-');
+        ret.append(mins);
+        ret.append(':');
+        if (secs < 10) ret.append('0');
+        ret.append(secs);
+        return ret.toString();
+    }
