        if (DBG) P.v("MPlayer - surfaceDestroyed");
        if (!isSurfaceReady()) {
            if (DBG) P.w("MPlayer - surfaceDestroyed is called at [NOT-surfaceReady]");
        }

        setSurfaceReady(false);
    }

