    private void
    onMpStateChanged(MPState from, int fromFlag,
                     MPState to,   int toFlag) {
        Iterator<PlayerStateListener> iter = mPStateLsnrl.iterator();
        while (iter.hasNext())
            iter.next().onStateChanged(from, fromFlag, to, toFlag);

        switch (to) {
        case PAUSED:
        case INVALID:
            releaseLocks();
            break;

        case STARTED:
            acquireLocks();
            break;

        case STOPPED:
            if (null != mLoader)
                mLoader.close();
            break;

        default:
            ; // ignored
        }
    }

