    @Override
    public void
    onCompletion(MediaPlayer mp) {
        if (DBG) P.v("MPlayer - onCompletion");
        mpSetState(MPState.PLAYBACK_COMPLETED);
        Runnable action = new Runnable() {
            @Override
            public void
            run() {
                startNext();
            }
        };

        if (mVlm.hasActiveVideo()
            && Utils.isPrefTailTTS()) {
