    @Override
    public void
    surfaceDestroyed(SurfaceHolder holder) {
        if (holder != mSurfHolder)
            logW("MPlayer - surfaceCreated with invalid holder");

        logD("MPlayer - surfaceDestroyed");
        if (!isSurfaceReady())
            logW("MPlayer - surfaceDestroyed is called at [NOT-surfaceReady]");

