    public Err
    prepare(WebView wv, OnPlayerReadyListener listener) {
        logI("YTJSPlayer : Prepare!!");
        mWv = wv;
        mPlayerReadyListener = listener;
        wv.setWebViewClient(new WVClient());
        wv.setWebChromeClient(new WCClient());
