	private void ResetReleaseLock() {
		if (isrecording) {
			mediaRecorder.reset();
			mediaRecorder.release();

			camera.lock();
			camera.release();
			mWakeLock.release();
		}
	}

	private void OpenUnlockPrepareStart() {
		if (!isrecording) {
			mWakeLock.acquire();
			try {
				camera = Camera.open(/* CameraInfo.CAMERA_FACING_BACK */);
                if(REVERSE_ORIENTATION) {
