            eAssert(Utils.isUiThread());
            vs = null;
            vi = -1;
            notifyToListChangedListener();
        }

        void
        setVideoList(Video[] aVs) {
            eAssert(Utils.isUiThread());
            vs = aVs;
            if (null == vs || 0 >= vs.length)
                reset();
            else if(vs.length > 0)
                vi = 0;
            notifyToListChangedListener();
        }

        Video[]
        getVideoList() {
            eAssert(Utils.isUiThread());
            return vs;
        }

        void
        appendVideo(Video v) {
            eAssert(Utils.isUiThread());
            Video[] newvs = new Video[vs.length + 1];
            System.arraycopy(vs, 0, newvs, 0, vs.length);
            newvs[newvs.length - 1] = v;
            // assigning reference is atomic operation in JAVA!
            vs = newvs;
            notifyToListChangedListener();
        }

        int
        getActiveVideoIndex() {
            return vi;
        }

        Video
        getActiveVideo() {
            eAssert(Utils.isUiThread());
            if (null != vs && 0 <= vi && vi < vs.length)
                return vs[vi];
            return null;
        }

        Video
        getNextVideo() {
            eAssert(Utils.isUiThread());
            if (!hasNextVideo())
                return null;
            return vs[vi + 1];
        }

        boolean
        moveToFist() {
            eAssert(Utils.isUiThread());
            if (hasActiveVideo()) {
                    vi = 0;
                    return true;
            }
            return false;
        }

        boolean
        moveToNext() {
            eAssert(Utils.isUiThread());
            if (hasActiveVideo()
                && vi < (vs.length - 1)) {
                vi++;
                return true;
            }
            return false;
        }

        boolean
        moveToPrev() {
            eAssert(Utils.isUiThread());
            if (hasActiveVideo()
                && vi > 0) {
                vi--;
                return true;
            }
            return false;
        }
    }

