    mapPrefToQScore(Utils.PrefQuality prefq) {
        switch (prefq) {
        case LOW:
            return YTHacker.YTQUALITY_SCORE_LOWEST;

        case MIDLOW:
            return YTHacker.YTQUALITY_SCORE_LOW;

        case NORMAL:
            return YTHacker.YTQUALITY_SCORE_MIDLOW;

        case HIGH:
            return YTHacker.YTQUALITY_SCORE_HIGH;

