+    @Override
+    protected void doOnResume() {
+        mPausing = false;
+        mOrientationEventListener.enable();
+
+        mCaptureState = CAPTURE_STATE_VIEWFINDER;
+        try {
+            setupCamera();
+
+            // Camera must be initialized before MosaicFrameProcessor is initialized.
