+					// TODO Auto-generated catch block
+					Log.v("OBD", "ReadError");
+					e.printStackTrace();
+				}
+			}
+			try {
+				inStream.reset();
+			} catch (IOException e) {
+				e.printStackTrace();
+			}
+		}
+	}
+}

