    private void
    mpPause() {
        logD("MPlayer - pause");
        if (null == mMp)
            return;

        switch (mpGetState()) {
        case STARTED:
        case PAUSED:
            mMp.pause();
            mpSetState(MPState.PAUSED);
            return;
        }
        logI("MP [" + mpGetState().name() + "] : pause ignored : ");
    }

    private void
    mpSeekTo(int pos) {
        logD("MPlayer - seekTo : " + pos);
        if (null == mMp)
            return;

        switch (mpGetState()) {
        case PREPARED_AUDIO:
        case PREPARED:
        case STARTED:
        case PAUSED:
        case PLAYBACK_COMPLETED:
            mpSetStateFlagBit(MPSTATE_FLAG_SEEKING);
            mMp.seekTo(pos);
            return;
        }
        logI("MP [" + mpGetState().name() + "] : seekTo ignored : ");
    }

    private void
    mpStart() {
        logD("MPlayer - start");
        if (null == mMp)
            return;

        if (ytpIsSuspended())
            return;

        switch (mpGetState()) {
        case PREPARED:
        case STARTED:
        case PAUSED:
        case PLAYBACK_COMPLETED:
            mMp.start();
            mpSetState(MPState.STARTED);
            return;
        }
        logI("MP [" + mpGetState().name() + "] : start ignored : ");
    }

    private void
    mpStop() {
        logD("MPlayer - stop");
        if (null == mMp)
            return;

        switch (mpGetState()) {
        case PREPARING:
        case PREPARED_AUDIO:
        case PREPARED:
        case STARTED:
        case PAUSED:
        case STOPPED:
        case PLAYBACK_COMPLETED:
            mMp.stop();
            mpSetState(MPState.STOPPED);
            return;
        }
        logI("MP [" + mpGetState().name() + "] : stop ignored : ");
    }

