    mpGetStateFlag() {
        return mMpSFlag;
    }

    private void
    mpSetStateFlagBit(int mask) {
        mpSetStateFlag(Utils.bitSet(mMpSFlag, mask, mask));
    }

    private void
    mpClearStateFlagBit(int mask) {
        mpSetStateFlag(Utils.bitClear(mMpSFlag, mask));
    }

