        if (DBG) P.v("MPlayer - pause");
        if (null == mMp)
            return;

        switch (mpGetState()) {
        case STARTED:
        case PAUSED:
            mMp.pause();
            mpSetState(MPState.PAUSED);
            return;

        default:
