            startAt(avi);
            mVlm.removeVideo(ytvid);
        } else {
            // remove first, and then stop to avoid 'repeat' in case that 'repeat' preference is set.
            mVlm.removeVideo(ytvid);
            // There is no video to play after remove.
            // Just stop playing.
            stopPlay(StopState.DONE);
