    private void
    onMpStateChanged(MPState from, int fromFlag,
                     MPState to,   int toFlag) {
        Iterator<PlayerStateListener> iter = mPStateLsnrl.iterator();
        while (iter.hasNext())
            iter.next().onStateChanged(from, fromFlag, to, toFlag);

        switch (to) {
        case PAUSED:
        case INVALID:
            releaseLocks();
            break;

        case STARTED:
            acquireLocks();
            break;

        case STOPPED:
            if (null != mLoader)
                mLoader.close();
            break;
        }
    }

    private boolean
    isPreparedCompletely() {
        return (!isVideoMode() && MPState.PREPARED_AUDIO == mpGetState())
                || (isVideoMode() && MPState.PREPARED_AUDIO == mpGetState()
                                  && isSurfaceReady()
                                  && isVideoSizeReady());
    }

    private int
    getVideoQualityScore() {
        switch (Utils.getPrefQuality()) {
        case LOW:
            return YTHacker.getQScorePreferLow(YTHacker.YTQUALITY_SCORE_LOWEST);

        case MIDLOW:
            return YTHacker.getQScorePreferLow(YTHacker.YTQUALITY_SCORE_LOW);

        case NORMAL:
            return YTHacker.getQScorePreferHigh(YTHacker.YTQUALITY_SCORE_MIDLOW);

        case HIGH:
            return YTHacker.getQScorePreferHigh(YTHacker.YTQUALITY_SCORE_HIGH);

        case VERYHIGH:
            return YTHacker.getQScorePreferHigh(YTHacker.YTQUALITY_SCORE_HIGHEST);
        }
        eAssert(false);
        return YTHacker.getQScorePreferLow(YTHacker.YTQUALITY_SCORE_LOWEST);
    }

