			pInfo = activity.getPackageManager().getApplicationInfo(
					activity.getClass().getPackage().getName(),
					PackageManager.GET_META_DATA);
			userid = pInfo.uid + "";
		} catch (NameNotFoundException e) {
			e.printStackTrace();
		}
		if (!(new File("/dev/net/tun")).exists()) {
			showAlertHtml(
					"TAP - User Id: " + userid,
