    public void
    setController(Activity  activity,
                  ViewGroup playerv,
                  ViewGroup playerLDrawer,
                  SurfaceView surfacev,
                  ToolButton toolBtn) {
        mUi.setController(activity, playerv, playerLDrawer, surfacev, toolBtn);

        if (!mVlm.hasActiveVideo())
            return;

        // controller is set again.
        // Than new surface may have to be used.
        // This is completely DIRTY and RISKY...
        // Until to find any other better way...
        // (I HATE THIS KIND OF HACK!!! :-( )
        if (!haveStoredPlayerState()
            && null != surfacev
            && null != mSurfHolder
            && surfacev.getHolder() == mSurfHolder
            && !mpIsSurfaceAttached()) {
            // Video surface should be set again.
            // This is Android MediaPlayer's constraints.
            // Video SHOULD BE re-started!
            backupPlayerState();
            mpStop();
        }

        if (haveStoredPlayerState())
            startVideo(mVlm.getActiveVideo(), false);
    }

    public void
    unsetController(Activity  activity) {
        mUi.unsetController(activity);
    }

    public void
    changeVideoVolume(final String title, final String videoId) {
        mUi.changeVideoVolume(title, videoId);
    }

    public boolean
    hasActiveVideo() {
        return mVlm.hasActiveVideo();
    }

    public boolean
    isVideoPlaying() {
        return mVlm.hasActiveVideo()
               && MPState.ERROR != mMpS
               && MPState.END != mMpS;
    }

    public boolean
    isPlayerSeeking(int stateFlag) {
        return Utils.bitIsSet(mpGetStateFlag(), MPSTATE_FLAG_SEEKING);
    }

    public boolean
    isPlayerBuffering(int stateFlag) {
        return Utils.bitIsSet(mpGetStateFlag(), MPSTATE_FLAG_BUFFERING);
    }

    /**
     * Get volume of video-on-play
     * @return
     *   -1 : for error
     */
    public int
    getVideoVolume() {
        if (isVideoPlaying())
            return mpGetVolume();
        return DB.INVALID_VOLUME;
    }

    public void
    restartFromCurrentPosition() {
        if (!mVlm.hasActiveVideo())
            return;
        backupPlayerState();
        startVideo(mVlm.getActiveVideo(), false);
    }

    public void
    startVideos(final Video[] vs) {
        eAssert(Utils.isUiThread());

        if (null == vs || vs.length <= 0)
            return;

        acquireLocks();
        clearStoredPlayerState();
        // removes auto stop that is set before.
        mAutoStop.unset();
        mVlm.setVideoList(vs);

        if (mVlm.moveToFist()) {
            startVideo(mVlm.getActiveVideo(), false);
            Iterator<VideosStateListener> iter = mVStateLsnrl.iterator();
            while (iter.hasNext())
                iter.next().onStarted();
            mUi.setPlayerVisibility(View.VISIBLE);
        }
    }

    public void
    startVideos(final Cursor c,
                final int coliYtvid,
                final int coliTitle,
                final int coliAuthor,
                final int coliVolume,
                final int coliPlaytime,
                final boolean shuffle) {
        eAssert(Utils.isUiThread());

        new Thread(new Runnable() {
            @Override
            public void run() {
                final Video[] vs = getVideos(c,
                                             coliYtvid, coliTitle, coliAuthor,
                                             coliVolume, coliPlaytime,
                                             shuffle);
                Utils.getUiHandler().post(new Runnable() {
                    @Override
                    public void run() {
                        startVideos(vs);
                    }
                });
                c.close();
            }
        }).start();
    }

    public void
    backupPlayerState() {
        storePlayerState();
    }

    public void
    appendToPlayQ(Video[] vids) {
        if (mVlm.hasActiveVideo())
            mVlm.appendVideo(vids);
        else
            startVideos(vids);
    }

    /**
     * player will be stopped after 'millis'
     * @param millis
     *   0 for unset autostop
     */
    public void
    setAutoStop(long millis) {
        mAutoStop.set(millis);
    }

    public void
    unsetAutoStop() {
        mAutoStop.unset();
    }

    public void
    stopVideos() {
        if (mVlm.hasActiveVideo())
            stopPlay(StopState.FORCE_STOPPED);
    }

    /**
     * Player session id.
     * Even if same video is re-played, session id is different.
     * @return
     */
    public long
    getPlayerSessionId() {
        return mMpSessId;
    }

    public MPState
    getPlayerState() {
        return mMpS;
    }

    public String
    getActiveVideoYtId() {
        if (isVideoPlaying())
            return mVlm.getActiveVideo().ytvid;
        return null;
    }

    public int
    getVideoWidth() {
        return mpGetVideoWidth();
    }

    public int
    getVideoHeight() {
        return mpGetVideoHeight();
    }

    public int
    getProgressPercent() {
        int progPercent = 0;
        if (mVlm.hasActiveVideo() && mpGetDuration() > 0)
            progPercent = (int)(mpGetCurrentPosition() * 100L / mpGetDuration());

        return progPercent;
    }
}

