    private boolean
    isMediaPlayerAvailable() {
        return null != mMp
               && State.END != mpGetState()
               && State.INVALID != mpGetState();
    }
    private void
    mpSetState(State newState) {
        logD("MusicPlayer : State : " + mMpS.name() + " => " + newState.name());
        State old = mMpS;
