    private void
    configurePlayerViewProgressBar() {
        if (null == mProgbar)
            return;

        switch (mpGetState()) {
        case STARTED:
            mUpdateProg.start(mProgbar);
            break;

        case PAUSED:
            mUpdateProg.end();
            break;

        default:
            mUpdateProg.end();
            mProgbar.setProgress(0);
        }
