            mMediaplayerHandler.removeMessages(FADEUP);
            if (isPlaying()) {
                mPlayer.pause();
                gotoIdleState();
                mIsSupposedToBePlaying = false;
                if(updateNotify) {
                    updateNotification();
                }
                notifyChange(PLAYSTATE_CHANGED);
                saveBookmarkIfNeeded();
            }else{
                gotoIdleState();
            }
        }
    }

