+                    mCurrentMediaPlayer = mNextMediaPlayer;
+                    mNextMediaPlayer = null;
+                    mHandler.sendEmptyMessage(TRACK_WENT_TO_NEXT);
+                } else {
+                    // Acquire a temporary wakelock, since when we return from
+                    // this callback the MediaPlayer will release its wakelock
+                    // and allow the device to go to sleep.
+                    // This temporary wakelock is released when the RELEASE_WAKELOCK
+                    // message is processed, but just in case, put a timeout on it.
+                    mWakeLock.acquire(30000);
+                    mHandler.sendEmptyMessage(TRACK_ENDED);
+                    mHandler.sendEmptyMessage(RELEASE_WAKELOCK);
+                }
+            }
+        };
+
+        MediaPlayer.OnErrorListener errorListener = new MediaPlayer.OnErrorListener() {
+            public boolean onError(MediaPlayer mp, int what, int extra) {
+                switch (what) {
+                    case MediaPlayer.MEDIA_ERROR_SERVER_DIED:
+                        mIsInitialized = false;
+                        mCurrentMediaPlayer.release();
+                        // Creating a new MediaPlayer and settings its wakemode does not
+                        // require the media service, so it's OK to do this now, while the
+                        // service is still being restarted
+                        mCurrentMediaPlayer = new CompatMediaPlayer();
+                        mCurrentMediaPlayer.setWakeMode(PlayerService.this, PowerManager.PARTIAL_WAKE_LOCK);
+                        mHandler.sendMessageDelayed(mHandler.obtainMessage(SERVER_DIED), 2000);
+                        return true;
+                    default:
+                        Log.d("MultiPlayer", "Error: " + what + "," + extra);
+                        break;
+                }
+                return false;
+            }
+        };
+
+        public long duration() {
+            return mCurrentMediaPlayer.getDuration();
+        }
+
+        public long position() {
+            return mCurrentMediaPlayer.getCurrentPosition();
+        }
+
+        public long seek(long whereto) {
+            mCurrentMediaPlayer.seekTo((int) whereto);
+            return whereto;
+        }
+
+        public void setVolume(float vol) {
+            mCurrentMediaPlayer.setVolume(vol, vol);
+        }
+
+        public void setAudioSessionId(int sessionId) {
+            mCurrentMediaPlayer.setAudioSessionId(sessionId);
+        }
+
+        public int getAudioSessionId() {
+            return mCurrentMediaPlayer.getAudioSessionId();
+        }
+    }
+
+    static class CompatMediaPlayer extends MediaPlayer implements MediaPlayer.OnCompletionListener {
+
+        private boolean mCompatMode = true;
+        private MediaPlayer mNextPlayer;
+        private OnCompletionListener mCompletion;
+
+        public CompatMediaPlayer() {
+            try {
+                MediaPlayer.class.getMethod("setNextMediaPlayer", MediaPlayer.class);
+                mCompatMode = false;
+            } catch (NoSuchMethodException e) {
+                mCompatMode = true;
+                super.setOnCompletionListener(this);
+            }
+        }
+
+        public void setNextMediaPlayer(MediaPlayer next) {
+            if (mCompatMode) {
+                mNextPlayer = next;
+            } else {
+                super.setNextMediaPlayer(next);
+            }
+        }
+
+        @Override
+        public void setOnCompletionListener(OnCompletionListener listener) {
+            if (mCompatMode) {
+                mCompletion = listener;
+            } else {
+                super.setOnCompletionListener(listener);
+            }
+        }
+
+        @Override
+        public void onCompletion(MediaPlayer mp) {
+            if (mNextPlayer != null) {
+                // as it turns out, starting a new MediaPlayer on the completion
+                // of a previous player ends up slightly overlapping the two
+                // playbacks, so slightly delaying the start of the next player
+                // gives a better user experience
+                SystemClock.sleep(50);
+                mNextPlayer.start();
+            }
+            mCompletion.onCompletion(this);
+        }
+    }
+
+    /*
+         * By making this a static class with a WeakReference to the Service, we
+         * ensure that the Service can be GCd even when the system process still
+         * has a remote reference to the stub.
+         */
+    static class ServiceStub extends IPlayerService.Stub {
+        WeakReference<PlayerService> mService;
+
+        ServiceStub(PlayerService service) {
+            mService = new WeakReference<PlayerService>(service);
+        }
+
+        public void openFile(String path)
+        {
+            mService.get().open(path);
+        }
+        public void open(long [] list, int position) {
+            mService.get().open(list, position);
+        }
+        public int getQueuePosition() {
+            return mService.get().getQueuePosition();
+        }
+        public void setQueuePosition(int index) {
+            mService.get().setQueuePosition(index);
+        }
+        public boolean isPlaying() {
+            return mService.get().isPlaying();
+        }
+        public void stop() {
+            mService.get().stop();
+        }
+        public void pause() {
+            mService.get().pause();
+        }
+        public void play() {
+            mService.get().play();
+        }
+        public void prev() {
+            mService.get().prev();
+        }
+        public void next() {
+            mService.get().gotoNext(true);
+        }
+        public String getTrackName() {
+            return mService.get().getTrackName();
+        }
+        public String getAlbumName() {
+            return mService.get().getAlbumName();
+        }
+        public long getAlbumId() {
+            return mService.get().getAlbumId();
+        }
+        public String getArtistName() {
+            return mService.get().getArtistName();
+        }
+        public long getArtistId() {
+            return mService.get().getArtistId();
+        }
+        public void enqueue(long [] list , int action) {
+            mService.get().enqueue(list, action);
+        }
+        public long [] getQueue() {
+            return mService.get().getQueue();
+        }
+        public String getPath() {
+            return mService.get().getPath();
+        }
+        public long getAudioId() {
+            return mService.get().getAudioId();
+        }
+        public long position() {
+            return mService.get().position();
+        }
+        public long duration() {
+            return mService.get().duration();
+        }
+        public long seek(long pos) {
+            return mService.get().seek(pos);
+        }
+        public void setShuffleMode(int shufflemode) {
+            mService.get().setShuffleMode(shufflemode);
+        }
+        public int getShuffleMode() {
+            return mService.get().getShuffleMode();
+        }
+        public void setRepeatMode(int repeatmode) {
+            mService.get().setRepeatMode(repeatmode);
+        }
+        public int getRepeatMode() {
+            return mService.get().getRepeatMode();
+        }
+        public int getMediaMountedCount() {
+            return mService.get().getMediaMountedCount();
+        }
+        public int getAudioSessionId() {
+            return mService.get().getAudioSessionId();
+        }
+    }
+
+    @Override
+    protected void dump(FileDescriptor fd, PrintWriter writer, String[] args) {
+        writer.println("" + mPlayListLen + " items in queue, currently at index " + mPlayPos);
+        writer.println("Currently loaded:");
+        writer.println(getArtistName());
+        writer.println(getAlbumName());
+        writer.println(getTrackName());
+        writer.println(getPath());
+        writer.println("playing: " + mIsSupposedToBePlaying);
+        writer.println("actual: " + mPlayer.mCurrentMediaPlayer.isPlaying());
+        writer.println("shuffle mode: " + mShuffleMode);
+        MusicUtils.debugDump(writer);
+    }
+
+    private final IBinder mBinder = new ServiceStub(this);
+
+    private class PlayerHandler extends Handler {
+        float mCurrentVolume = 1.0f;
+
+        public PlayerHandler(Looper looper){
+            super(looper);
+        }
+
+        @Override
+        public void handleMessage(Message msg) {
+            switch (msg.what) {
+                case FADEDOWN:
+                    mCurrentVolume -= .05f;
+                    if (mCurrentVolume > .2f) {
+                        mMediaplayerHandler.sendEmptyMessageDelayed(FADEDOWN, 10);
+                    } else {
+                        mCurrentVolume = .2f;
+                    }
+                    mPlayer.setVolume(mCurrentVolume);
+                    break;
+                case FADEUP:
+                    mCurrentVolume += .01f;
+                    if (mCurrentVolume < 1.0f) {
+                        mMediaplayerHandler.sendEmptyMessageDelayed(FADEUP, 10);
+                    } else {
+                        mCurrentVolume = 1.0f;
+                    }
+                    mPlayer.setVolume(mCurrentVolume);
+                    break;
+                case SERVER_DIED:
+                    if (mIsSupposedToBePlaying) {
+                        gotoNext(true);
+                    } else {
+                        // the server died when we were idle, so just
+                        // reopen the same song (it will start again
+                        // from the beginning though when the user
+                        // restarts)
+                        openCurrentAndNext();
+                    }
+                    break;
+                case TRACK_WENT_TO_NEXT:
+                    mPlayPos = mNextPlayPos;
+                    if (mCursor != null) {
+                        mCursor.close();
+                        mCursor = null;
+                    }
+                    mCursor = getCursorForId(mPlayList[mPlayPos]);
+                    notifyChange(META_CHANGED);
+                    updateNotification();
+                    setNextTrack();
+                    break;
+                case TRACK_ENDED:
+                    if (mRepeatMode == REPEAT_CURRENT) {
+                        seek(0);
+                        play();
+                    } else {
+                        gotoNext(false);
+                    }
+                    break;
+                case RELEASE_WAKELOCK:
+                    mWakeLock.release();
+                    break;
+
+                case FOCUSCHANGE:
+                    // This code is here so we can better synchronize it with the code that
+                    // handles fade-in
+                    switch (msg.arg1) {
+                        case AudioManager.AUDIOFOCUS_LOSS:
+                            Log.v(LOGTAG, "AudioFocus: received AUDIOFOCUS_LOSS");
+                            if(isPlaying()) {
+                                mPausedByTransientLossOfFocus = false;
+                            }
+                            pause();
+                            break;
+                        case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK:
+                            mMediaplayerHandler.removeMessages(FADEUP);
+                            mMediaplayerHandler.sendEmptyMessage(FADEDOWN);
+                            break;
+                        case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT:
+                            Log.v(LOGTAG, "AudioFocus: received AUDIOFOCUS_LOSS_TRANSIENT");
+                            if(isPlaying()) {
+                                mPausedByTransientLossOfFocus = true;
+                            }
+                            pause();
+                            break;
+                        case AudioManager.AUDIOFOCUS_GAIN:
+                            Log.v(LOGTAG, "AudioFocus: received AUDIOFOCUS_GAIN");
+                            if(!isPlaying() && mPausedByTransientLossOfFocus) {
+                                mPausedByTransientLossOfFocus = false;
+                                mCurrentVolume = 0f;
+                                mPlayer.setVolume(mCurrentVolume);
+                                play(); // also queues a fade-in
+                            } else {
+                                mMediaplayerHandler.removeMessages(FADEDOWN);
+                                mMediaplayerHandler.sendEmptyMessage(FADEUP);
+                            }
+                            break;
+                        default:
+                            Log.e(LOGTAG, "Unknown audio focus change code");
+                    }
+                    break;
+
+                default:
+                    break;
+            }
+        }
+    };
+
+
+}

