    private void
    mpSetSubState(MPSubState newSubState) {
        logD("MusicPlayer : SubState : " + mMpSubS.name() + " => " + newSubState.name());
        MPSubState oldSubS = mMpSubS;
        mMpSubS = newSubState;
        onMpStateChanged(mMpS, oldSubS, mMpS, mMpSubS);
    }

