			mPlayOrder = generateArray(0, mPlayListLen);
			if (shufflemode == SHUFFLE_NORMAL) {
				shuffleArray(mPlayOrder);
			}
			mShuffleMode = shufflemode;
			notifyChange(SHUFFLEMODE_CHANGED);
		}
	}

