    }

    MPState
    playerGetState() {
        return mpGetState();
    }

    void
    playerStart() {
        if (isVideoPlaying()
            && MPState.PREPARING != mpGetState())
            mpStart();
    }

    void
    playerPause() {
        if (isVideoPlaying()
