    private void
    onMpStateChanged(MPState from, MPState to) {
        if (from == to)
            return;

        pvConfigureAll(mPlayerv, from, to);
        switch (to) {
        case PAUSED:
            releaseLocks();
            break;

        case STARTED:
            acquireLocks();
            break;
        }
    }

    private void
    startVideo(final String videoId, int volume) {
        startVideo(videoId, volume, false);
    }


    private void
    startVideo(final String videoId, int volume, boolean recovery) {
        eAssert(0 <= volume && volume <= 100);

        if (recovery)
            mErrRetry--;
        else
            mErrRetry = PLAYER_ERR_RETRY;

        // Stop if player is already running.
        mpStop();
        mpRelease();
        mpNewInstance();
        mpReset();
        mpSetVolume(volume);

        YTVideoConnector.YtVideoConnListener listener = new YTVideoConnector.YtVideoConnListener() {
            @Override
            public void
            onPreConn(YTVideoConnector ytconn, String ytvid, Object user) {
            }

            @Override
            public void
            onPostConn(YTVideoConnector ytconn, Err result, String ytvid, Object user) {
                mYtConn = null;

                if (Err.NO_ERR != result) {
                    logW("YTVideoConnector Fails : " + result.name());
                    return;
                }

                YTVideoConnector.YtVideo ytv = ytconn.getVideo(YTVideoConnector.YTQUALITY_SCORE_LOWEST);
                try {
                    mpSetDataSource(Uri.parse(ytv.url));
                } catch (IOException e) {
                    eAssert(false);
                }
                mpPrepareAsync();
            }

            @Override
            public void
            onConnCancelled(YTVideoConnector ytconn, String ytvid, Object user) {
                mYtConn = null;
            }
        };
        mYtConn = new YTVideoConnector(videoId, volume, listener);
        mYtConn.execute();
    }

    private void
    startNext() {
        if (null == mVideos)
            return; // do nothing

        mVideoi++;
        if (mVideoi >= mVideos.length) {
            mVideoi = mVideos.length;
            playDone(false);
        } else
            startVideo(mVideos[mVideoi].videoId, mVideos[mVideoi].volume);
    }

    private void
    startPrev() {
        if (null == mVideos)
            return; // do nothing

        mVideoi--;
        if (mVideoi < 0) {
            mVideoi = -1;
            playDone(false);
        } else
            startVideo(mVideos[mVideoi].videoId, mVideos[mVideoi].volume);
    }

    private void
    playDone(boolean forceStop) {
        logD("VideoView - playDone : forceStop (" + forceStop + ")");

        if (!forceStop && Utils.isPrefRepeat()) {
            startVideos(mVideos);
            return;
        }

        mpStop();
        mpRelease();
        releaseLocks();
        mVideos = null;
        mVideoi = -1;
        if (null != mPlayerv) {
            if (forceStop)
                pvSetTitle((TextView)mPlayerv.findViewById(R.id.music_player_title),
                        mRes.getText(R.string.msg_playing_stopped), false);
            else
                pvSetTitle((TextView)mPlayerv.findViewById(R.id.music_player_title),
                            mRes.getText(R.string.msg_playing_done), false);
        }
    }


