    private class UpdateProgress implements Runnable {
        private SeekBar     seekbar = null;
        private TextView    curposv = null;
        private TextView    maxposv = null;
        private int         lastProgress = -1;
        private int         lastSecondaryProgress = -1; // For secondary progress

        private void
        resetProgressView() {
            if (null != seekbar) {
                maxposv.setText(Utils.secsToMinSecText(mpGetDuration() / 1000));
                update(1, 0);
                updateSecondary(0);
            }
            lastProgress = 0;
            lastSecondaryProgress = 0;
        }

        int getSecondaryProgressPercent() {
            int percent =  lastSecondaryProgress * 100 / SEEKBAR_MAX;
            if (percent > 100)
                percent = 100;
            if (percent < 0)
                percent = 0;
            return percent;
        }

        void setProgressView(ViewGroup progv) {
            eAssert(Utils.isUiThread());
            eAssert(null != progv.findViewById(R.id.music_player_progress));
            curposv = (TextView)progv.findViewById(R.id.music_player_curpos);
            maxposv = (TextView)progv.findViewById(R.id.music_player_maxpos);
            seekbar = (SeekBar)progv.findViewById(R.id.music_player_seekbar);
            if (null != seekbar) {
                maxposv.setText(Utils.secsToMinSecText(mpGetDuration() / 1000));
                update(mpGetDuration(), lastProgress);
                updateSecondary(lastSecondaryProgress);
            }
        }

        void start() {
            //logI("Progress Start");
            maxposv.setText(Utils.secsToMinSecText(mpGetDuration() / 1000));
            update(mpGetDuration(), lastProgress);
            updateSecondary(lastSecondaryProgress);
            run();
        }

        void stop() {
            //logI("Progress End");
            Utils.getUiHandler().removeCallbacks(this);
            resetProgressView();
        }

        void update(int durms, int curms) {
            // ignore aDuration.
            // Sometimes youtube player returns incorrect duration value!
            if (null != seekbar) {
                int curPv = (durms > 0)? (int)((long)curms * (long)SEEKBAR_MAX / durms)
                                               : 0;
                seekbar.setProgress(curPv);
                curposv.setText(Utils.secsToMinSecText(curms / 1000));
                lastProgress = curPv;
            }
        }

        /**
         * Update secondary progress
         * @param percent
         */
        void updateSecondary(int percent) {
            // Update secondary progress
            if (null != seekbar) {
                int pv = percent * SEEKBAR_MAX / 100;
                seekbar.setSecondaryProgress(pv);
                lastSecondaryProgress = pv;
            }
        }

        @Override
        public void run() {
            update(mpGetDuration(), mpGetCurrentPosition());
            Utils.getUiHandler().postDelayed(this, 1000);
        }
    }

    private static class VideoListManager {
        private Video[]     vs  = null; // video array
        private int         vi  = -1; // video index

        boolean hasActiveVideo() {
            eAssert(Utils.isUiThread());
            return null != getActiveVideo();
        }

        boolean hasNextVideo() {
            eAssert(Utils.isUiThread());
            return hasActiveVideo()
                   && vi < (vs.length - 1);
        }

        boolean hasPrevVideo() {
            eAssert(Utils.isUiThread());
            return hasActiveVideo() && 0 < vi;
        }

        void reset() {
            eAssert(Utils.isUiThread());
            vs = null;
            vi = -1;
        }

        void setVideoList(Video[] aVs) {
            eAssert(Utils.isUiThread());
            vs = aVs;
            if (null == vs || 0 >= vs.length)
                reset();
            else if(vs.length > 0)
                vi = 0;
        }

        void appendVideo(Video v) {
            eAssert(Utils.isUiThread());
            Video[] newvs = new Video[vs.length + 1];
            System.arraycopy(vs, 0, newvs, 0, vs.length);
            newvs[newvs.length - 1] = v;
            // assigning reference is atomic operation in JAVA!
            vs = newvs;
        }

        Video getActiveVideo() {
            eAssert(Utils.isUiThread());
            if (null != vs && 0 <= vi && vi < vs.length)
                return vs[vi];
            return null;
        }

        Video getNextVideo() {
            eAssert(Utils.isUiThread());
            if (!hasNextVideo())
                return null;
            return vs[vi + 1];
        }

        boolean moveToFist() {
            eAssert(Utils.isUiThread());
            if (hasActiveVideo()) {
                    vi = 0;
                    return true;
            }
            return false;
        }

        boolean moveToNext() {
            eAssert(Utils.isUiThread());
            if (hasActiveVideo()
                && vi < (vs.length - 1)) {
                vi++;
                return true;
            }
            return false;
        }

        boolean moveToPrev() {
            eAssert(Utils.isUiThread());
            if (hasActiveVideo()
                && vi > 0) {
                vi--;
                return true;
            }
            return false;
        }
    }


