		FileUtils fileutils = new FileUtils();
		try {
			showAlertHtml("TAP - User Id: " + userid,
					fileutils.LoadFile(activity, "TAP", false), OShandler);
		} catch (IOException e) {
			// TODO Auto-generated catch block
			e.printStackTrace();
		}
	}

