	{
		if (number.length() == 12)
			return number.substring(0,3) + number.substring(4,7) +  number.substring(8,12);
		else if (number.length() == 14)
			return number.substring(0,1) + number.substring(2,5) +  number.substring(6,9) + number.substring(10,14);

		return number;
	}

