			@Override
			public void dispatchMessage(Message msg) {
				switch (msg.what) {
				/*case 1:
					final byte[] data = (byte[]) msg.obj;
					ThreadPoolUtils.execute(new Runnable() {

						@Override
						public void run() {
							getFirstCapture(data);
						}
