			// Log.v(TAG, "No machine in DB");
			length = 0;
		} else {
			// Log.v("PopMachines", "Found " + length + " machines in DB");
			length = machines.size();
		}

		String[] arraySpinner = new String[machines.size() + 2];
		arraySpinner[0] = "Open";
		arraySpinner[1] = "New";
		int index = 2;
		Iterator i = machines.iterator();
		while (i.hasNext()) {
			String file = (String) i.next();
