				android.R.layout.simple_spinner_item, arraySpinner);
		machineAdapter
				.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
		this.mMachine.setAdapter(machineAdapter);
		this.mMachine.invalidate();

	}

