+    /**
+     * player will be stopped after 'millis'
+     * @param millis
+     *   0 for disable autostop
+     */
+    private void
+    setAutoStop(long millis) {
+        Utils.getUiHandler().removeCallbacks(mAutoStop);
+        if (millis > 0)
+            Utils.getUiHandler().postDelayed(mAutoStop, millis);
